import heapq
from typing import Dict, List, Tuple, Union

def shortest_path(graph: Dict[str, List[Tuple[str, float]]], start: str, end: str) -> Tuple[float, List[str]]:
    """
    Implements Dijkstra's algorithm to find the shortest path from start to end in a directed weighted graph.
    Returns a tuple containing the shortest distance and the path taken.
    """
    if start not in graph or end not in graph:
        return float('inf'), []

    queue = [(0, start)]
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous_nodes = {node: None for node in graph}
    visited = set()

    while queue:
        current_distance, current_node = heapq.heappop(queue)

        if current_node in visited:
            continue

        visited.add(current_node)

        for neighbor, weight in graph[current_node]:
            if neighbor in visited:
                continue

            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(queue, (distance, neighbor))

    path = []
    current = end
    while current is not None:
        path.append(current)
        current = previous_nodes[current]

    path.reverse()

    return (distances[end], path) if distances[end] < float('inf') else (float('inf'), [])
